-- 0120_industry_taxonomy: UK SIC 2026 as ClientTurn's canonical economic-
-- activity classification (brief §4), with SIC 2007 alongside it.
--
-- Source: ONS "UK SIC: 2026" (final April 2026; files dated 3 Aug 2026).
-- Evidence: docs/revenue-engine/01-evidence-register.md §1. The data section
-- below is generated by scripts/build-sic-taxonomy.py from the ONS files kept
-- in scripts/data/sic/ -- regenerate rather than hand-editing it.
--
-- ## Why two systems
--
-- SIC 2026 is the current classification, but Companies House filings still
-- carry SIC 2007 codes and no adoption date has been published. A company's
-- register code therefore arrives as 2007 and is mapped to 2026 through the
-- ONS correspondence table. Many 2007 codes map to several 2026 codes, so a
-- mapping yields *candidates*, never an automatic single answer.
--
-- ## Extensible by design
--
-- `system` is free text so NACE, NAICS, ANZSIC or a customer's own taxonomy
-- can be added later as further systems plus mappings, without a schema change.
--
-- ## Access
--
-- Platform reference data, not tenant data: no business_id. RLS on with no
-- policies, matching the other server-only reference tables -- read through
-- server code, never directly from the browser.

create table public.industry_codes (
  system text not null,
  code text not null,
  -- Companies House five-digit form for class/subclass rows; null above class.
  numeric_code text,
  level text not null check (level in ('SECTION','DIVISION','GROUP','CLASS','SUBCLASS')),
  title text not null,
  parent_code text,
  section text,
  created_at timestamptz not null default now(),
  primary key (system, code)
);

create index industry_codes_numeric_idx on public.industry_codes (system, numeric_code)
  where numeric_code is not null;
create index industry_codes_parent_idx on public.industry_codes (system, parent_code);

create table public.industry_code_mappings (
  from_system text not null,
  from_code text not null,
  to_system text not null,
  to_code text not null,
  -- ONS correspondence type, e.g. '1:1', '1:3', '3:1'.
  correspondence text,
  primary key (from_system, from_code, to_system, to_code)
);

-- Plain-language terms a customer types ("web design", "MSP") mapped onto codes.
-- Seeded with the business archetypes (0121), extended over time.
create table public.industry_aliases (
  system text not null,
  code text not null,
  alias text not null,
  primary key (system, code, alias),
  foreign key (system, code) references public.industry_codes (system, code) on delete cascade
);

create index industry_aliases_alias_idx on public.industry_aliases (lower(alias));

alter table public.industry_codes enable row level security;
alter table public.industry_code_mappings enable row level security;
alter table public.industry_aliases enable row level security;

-- Generated by scripts/build-sic-taxonomy.py from ONS UK SIC 2026 files (3 Aug 2026).
-- Do not edit by hand; regenerate instead.

on conflict (system, code) do update set title = excluded.title;

on conflict do nothing;
